<div class="admin-two-col admin-section-gap">
<section class="card"><h2>Supplier-product terms</h2><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="supplier_id" value="<?= $id ?>"><input type="hidden" name="action" value="offer"><div class="form-grid">
<div class="field full"><label>Product</label><select name="product_id" required><option value="">Choose product</option><?php foreach($products as $p):?><option value="<?= (int)$p['id'] ?>"><?= e($p['sku'].' · '.$p['name']) ?></option><?php endforeach;?></select></div><div class="field"><label>Supplier SKU</label><input name="supplier_sku" maxlength="100"></div><div class="field"><label>Availability</label><select name="availability"><option>Unknown</option><option>Available</option><option>Backorder</option><option>Custom order</option><option>Unavailable</option></select></div><div class="field"><label>Wholesale price</label><input type="number" step="0.01" min="0" name="wholesale_price"></div><div class="field"><label>Currency</label><input name="currency" maxlength="3" value="<?= e(strtoupper($supplier['region'] ?? '') === 'USA' ? 'USD' : 'ZAR') ?>"></div><div class="field"><label>MOQ units</label><input type="number" min="0" name="moq_units"></div><div class="field"><label>MOQ value</label><input type="number" step="0.01" min="0" name="moq_value"></div><div class="field"><label>Lead time (days)</label><input type="number" min="0" name="lead_time_days"></div><div class="field admin-checks"><label><input type="checkbox" name="coa_available"> COA available</label><label><input type="checkbox" name="private_label"> Private label</label><label><input type="checkbox" name="dropship"> Dropship</label></div><div class="field full"><label>Notes</label><textarea name="offer_notes" maxlength="5000"></textarea></div><div class="field full"><button class="btn primary">Save / update terms</button></div></div></form></section>
<section class="card"><h2>Recorded offers</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Product</th><th>Wholesale</th><th>MOQ</th><th>Lead</th><th>Capabilities</th></tr></thead><tbody><?php foreach($offers as $o):?><tr><td><?= e($o['sku'].' · '.$o['product_name']) ?></td><td><?= sourcing_money($o['wholesale_price'],$o['currency']) ?></td><td><?= $o['moq_units']!==null?(int)$o['moq_units'].' units':($o['moq_value']!==null?sourcing_money($o['moq_value'],$o['currency']):'—') ?></td><td><?= $o['lead_time_days']!==null?(int)$o['lead_time_days'].'d':'—' ?></td><td><?= $o['coa_available']?'COA ':'' ?><?= $o['private_label']?'Private-label ':'' ?><?= $o['dropship']?'Dropship':'' ?></td></tr><?php endforeach;?><?php if(!$offers):?><tr><td colspan="5">No commercial terms yet.</td></tr><?php endif;?></tbody></table></div></section>
</div>
